import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import com.google.gson.*;

/** Original earned personal shield and battery operations. */
public class VerifyPersonalShield extends VerifyOwnedPlayerFirearm {
    JsonArray shieldEvents=new JsonArray();
    @Override void observe(ActionOracleHarness h,RunResult r,long pc)throws Exception{
        super.observe(h,r,pc);
        if(pc==0x164a0e||pc==0x14ef76||pc==0x14e5e4||pc==0x150b30||pc==0x150b44||pc==0x150c18){JsonObject e=new JsonObject();e.addProperty("address",Long.toHexString(pc));e.addProperty("d0",h.cpu.readRegister("D0").longValue());e.addProperty("draws",r.draws);JsonArray args=new JsonArray();for(int i=0;i<(pc==0x164a0e?3:4);i++)args.add(h.word(h.sp()+4+i*2));e.add("arguments",args);e.addProperty("return",Long.toHexString(h.pointer(h.sp())));shieldEvents.add(e);}
    }
    JsonObject shieldSnap(ActionOracleHarness h,RunResult r){JsonObject s=ownedSnap(h,r);JsonArray caches=new JsonArray();for(long a:new long[]{0x4537fe,0x46225e,0x45ad2e,0x46978e,0x470cbe})caches.add(hex(h.read(a,30000)));s.add("definition_caches",caches);s.add("shield_events",shieldEvents.deepCopy());return s;}
    int slotInCrate(ActionOracleHarness h,int id){for(int i=0;i<1000;i++)if(h.word(0x4285f4+i*22)==id)return i;throw new IllegalStateException("Missing earned item"+id);}
    int take(ActionOracleHarness h,RunResult r,int member,int id)throws Exception{int cr=slotInCrate(h,id),slot=h.word(0x448aa0+member*3138+26);h.write(0x41fc74,h.read(0x4285f4,22000));if(pickup(h,r,member,cr)!=1)throw new Exception("Earned pickup rejected"+id);closeCrate(h,r);return slot;}
    void begin(ActionOracleHarness h,RunResult r){initialize(h,r,3);shieldEvents=new JsonArray();}
    void gateCase(JsonArray out,int id,int member)throws Exception{ActionOracleHarness h=frame();RunResult r=new RunResult(foundation.getAsJsonObject("random").get("seed").getAsLong());r.draws=foundation.getAsJsonObject("random").get("draws").getAsInt();try{begin(h,r);JsonObject j=new JsonObject();j.addProperty("item_id",id);j.addProperty("member",member);j.add("before",shieldSnap(h,r));j.addProperty("allowed",call(h,r,0x157586,id,h.word(0x448aa0+member*3138+50),h.word(0x448aa0+member*3138+52)));j.add("after",shieldSnap(h,r));out.add(j);}finally{h.cpu.dispose();}}
    void equipmentCase(JsonArray out,int source,boolean manual)throws Exception{ActionOracleHarness h=frame();RunResult r=new RunResult(foundation.getAsJsonObject("random").get("seed").getAsLong());r.draws=foundation.getAsJsonObject("random").get("draws").getAsInt();try{begin(h,r);JsonObject j=new JsonObject();j.addProperty("source",source);j.addProperty("kind",manual?"manual":"automatic");j.addProperty("member",3);j.add("before",shieldSnap(h,r));int shield=take(h,r,3,600);selectMember(h,3,shield);j.add("shield_picked",shieldSnap(h,r));j.addProperty("empty_shield_wear_return",call(h,r,0x164a0e,3,shield,1));j.add("empty_shield_worn",shieldSnap(h,r));int battery=take(h,r,3,637);selectMember(h,3,battery);j.add("battery_picked",shieldSnap(h,r));j.addProperty("battery_wear_return",call(h,r,0x164a0e,3,battery,1));j.add("battery_worn",shieldSnap(h,r));if(manual){selectMember(h,3,battery);manualCharge(h,r);}else j.addProperty("refit_return",call(h,r,0x14e5e4,3,0,0,0));j.add("refitted",shieldSnap(h,r));selectMember(h,3,shield);j.addProperty("shield_wear_return",call(h,r,0x164a0e,3,shield,1));j.add("worn",shieldSnap(h,r));call(h,r,0x12006e,3);shield=locate(h,3,600);battery=locate(h,3,637);j.add("compacted",shieldSnap(h,r));selectMember(h,3,battery);j.addProperty("battery_remove_with_shield_return",call(h,r,0x14ef76,3,battery,1,0));j.add("battery_remove_rejected",shieldSnap(h,r));selectMember(h,3,shield);j.addProperty("shield_remove_return",call(h,r,0x14ef76,3,shield,1,0));j.add("shield_removed",shieldSnap(h,r));selectMember(h,3,battery);j.addProperty("battery_remove_return",call(h,r,0x14ef76,3,battery,1,0));j.add("battery_removed",shieldSnap(h,r));selectMember(h,3,battery);j.addProperty("battery_rewear_return",call(h,r,0x164a0e,3,battery,1));j.add("battery_reworn",shieldSnap(h,r));selectMember(h,3,shield);j.addProperty("shield_rewear_return",call(h,r,0x164a0e,3,shield,1));call(h,r,0x12006e,3);j.add("after",shieldSnap(h,r));out.add(j);println("Personal shield actual equipment source"+source);}finally{h.cpu.dispose();}}
    void manualCharge(ActionOracleHarness h,RunResult r)throws Exception{h.cpu.writeRegister("A6",0x700000);h.cpu.writeRegister("SP",0x6ffe00);h.jump(0x12bfb8);secondaryStop=0x13071c;execute(h,r,0x12c004);secondaryStop=0;if(h.pc()!=0x13071c)throw new Exception("Manual battery chooser absent");long frame=h.cpu.readRegister("A6").longValue();int count=h.word(frame-0x266),choice=0;JsonArray candidates=new JsonArray();for(int i=0;i<count;i++){int c=h.word(frame-0x264+i*2);candidates.add(c);if(c==107)choice=i+2;}JsonObject e=new JsonObject();e.add("candidates",candidates);e.addProperty("popup_result",choice);guiSelections.add(e);h.cpu.writeRegister("D6",choice);h.jump(0x13075c);execute(h,r,0x12c004);}
    void manualControl(JsonArray out,int reserve,boolean repeat)throws Exception{ActionOracleHarness h=frame();RunResult r=new RunResult(foundation.getAsJsonObject("random").get("seed").getAsLong());r.draws=foundation.getAsJsonObject("random").get("draws").getAsInt();try{begin(h,r);int shield=take(h,r,3,600),battery=take(h,r,3,637);selectMember(h,3,battery);call(h,r,0x164a0e,3,battery,1);if(reserve>=0)h.value(0x42dbe4+107*4,4,reserve);JsonObject j=new JsonObject();j.addProperty("reserve307",reserve);j.addProperty("repeat",repeat);j.add("before",shieldSnap(h,r));manualCharge(h,r);j.add("charged",shieldSnap(h,r));if(repeat){manualCharge(h,r);j.add("repeated",shieldSnap(h,r));}selectMember(h,3,shield);j.addProperty("shield_wear_return",call(h,r,0x164a0e,3,shield,1));j.add("after",shieldSnap(h,r));out.add(j);}finally{h.cpu.dispose();}}
    public void run()throws Exception{
        Path root=Path.of(getScriptArgs()[0]),original=root.resolve("NewCenturions/TheNewCenturions"),scenario=original.resolve("Scenarios/The Thunder of Guns/0");items=Files.readAllBytes(original.resolve("Data Files/Data ID"));scenarioItems=Files.readAllBytes(scenario.resolve("Data NI"));races=Files.readAllBytes(original.resolve("Data Files/Data Race"));mos=Files.readAllBytes(original.resolve("Data Files/Data MOS"));monsters=Files.readAllBytes(scenario.resolve("Data MD"));properties=Files.readAllBytes(original.resolve("Data Files/Data Swamp BD"));attacks=Files.readAllBytes(original.resolve("Data Files/Data S"));areas=Files.readAllBytes(original.resolve("Data Files/Data AD"));JsonObject identity=JsonParser.parseString(Files.readString(root.resolve("evidence/fixtures/owned-player-firearm.json"))).getAsJsonObject().getAsJsonObject("identity").deepCopy();identity.addProperty("owned_probe_sha256",identity.get("probe_sha256").getAsString());identity.addProperty("probe_sha256",ActionOracleHarness.sha256(root.resolve("tools/ghidra/VerifyPersonalShield.java")));identity.addProperty("owned_fixture_sha256",ActionOracleHarness.sha256(root.resolve("evidence/fixtures/owned-player-firearm.json")));JsonArray sources=new JsonArray(),gates=new JsonArray(),equipment=new JsonArray(),controls=new JsonArray();
        for(int source:new int[]{12,1}){String input="analysis/completion/laboratory-"+source+".json";foundation=JsonParser.parseString(Files.readString(root.resolve(input))).getAsJsonObject().getAsJsonObject("session");party=warriors(foundation);JsonObject f=new JsonObject();f.addProperty("input",input);f.addProperty("digest",ActionOracleHarness.sha256(root.resolve(input)));f.add("session",foundation);sources.add(f);if(source==12)for(int id:new int[]{600,637})for(int member=0;member<6;member++)gateCase(gates,id,member);equipmentCase(equipment,source,false);equipmentCase(equipment,source,true);if(source==12){for(int reserve:new int[]{0,1,2,250})manualControl(controls,reserve,false);manualControl(controls,-1,true);}}
        JsonObject out=new JsonObject();out.addProperty("authority","Original earned600/637 pickup and full wear/refit on exact current laboratory12/1 snapshots with their actual RNG state; native profile admission and complete party/crate/reserve/work/cache bytes captured. Presentation and SANE boundaries inherited. Full manual Items charge and distinct automatic-refit controls, removal-order and rewear compositions; no protected shot or live original-game claim.");out.add("identity",identity);out.add("foundations",sources);out.add("gate_cases",gates);out.add("equipment_cases",equipment);out.add("manual_controls",controls);Files.writeString(root.resolve("evidence/fixtures/personal-shield.json"),out+"\n");println("Personal shield initial equipment exported");
    }
}
